class ParameterEditorPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on Parameter Editor will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'Configuration Management', 'Parameter Editor']

    def __init__(self, driver, download_checker, screenshot_dir):
        super(ParameterEditorPage, self).__init__(driver)
        self._navigation_panel = ParameterEditorPageNavigationPanel(driver, screenshot_dir)
        self._view_panel = ParameterEditorPageViewPanel(driver, download_checker)
        self._detail_panel = ParameterEditorPageDetailPanel(driver, download_checker)
        self.common_actions = {
            'add_object': self._navigation_panel.add_object,
            'add_new_object': self._navigation_panel.add_new_object,
            'copy_existing_object': self._navigation_panel.copy_existing_object,
            'remove_object': self._navigation_panel.remove_object,
            'undo_object_changes': self._navigation_panel.undo_object_changes,
            'create_plan': self._view_panel.create_plan,
            'load_commissioning_file_and_check_load_status':
                self._view_panel.load_commissioning_file_and_check_load_status,
            'undo_changes': self._view_panel.undo_changes,
            'validate_plan': self._view_panel.validate_plan,
            'activate_plan': self._view_panel.activate_plan,
            'save_report': self._view_panel.save_report,
            'save_bts_configuration': self._view_panel.save_bts_configuration,
        }
        self.__dict__.update(self.common_actions)

    def get_parameter_value_by_global_search(self, filter_param, timeout=60):
        return self._view_panel.get_parameter_value_by_global_search(filter_param, timeout)

    def get_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None, bts_configuration='Current',
                            timeout=60):
        """
        Keyword for getting parameter value at Parameter Editor view
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :param timeout: int, timeout
        :return: str, the value corresponding to filter_param
        """
        return self._view_panel.get_parameter_value(dist_name, filter_param, node_index, abbr, bts_configuration,
                                                    timeout)

    def get_planned_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None,
                                    bts_configuration='Current', timeout=60):
        return self._view_panel.get_planned_parameter_value(dist_name, filter_param, node_index, abbr,
                                                            bts_configuration, timeout)

    def set_parameter_value(self, dist_name, filter_param, new_value, node_index=None,
                            parameter_status="All parameters", abbr=None, bts_configuration='Current', timeout=60):
        self._view_panel.set_parameter_value(dist_name, filter_param, new_value, node_index,
                                             parameter_status, abbr, bts_configuration, timeout)

    def get_error_info_after_set_parameter(self, timeout=2):
        """
        Keyword for getting parameter error info after setting parameter value
        """
        return self._view_panel.get_error_info_after_set_parameter(timeout)

    def add_element(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Keyword for adding element under child node of one object
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.add_element(dist_name, filter_param, abbr, timeout)

    def remove_element(self, dist_name, filter_param, node_index=0, abbr=None, timeout=60):
        """
        Keyword for removing element under child node of one object
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.remove_element(dist_name, filter_param, node_index, abbr, timeout)

    def delete_parameter(self, dist_name, filter_param, node_index=None, abbr=None, timeout=60):
        """
        Delete parameter
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param node_index: int, param to filter child node if other params can not locate only one
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        """
        self._view_panel.delete_parameter(dist_name, filter_param, node_index, abbr, timeout)

    def get_parameter_details(self, dist_name, filter_param, abbr=None, timeout=60):
        """
        Keyword for getting parameter details at Parameter Editor view
        :param dist_name: str, dist name for parameters to filter, cannot be none
        :param filter_param: str, param to locate target parameter, cannot be none
        :param abbr: str, optional, abbreviation to further locate target parameter
        :param timeout: int, timeout
        :return: dict of str
        """
        return self._detail_panel.get_parameter_details(dist_name, filter_param, abbr, timeout)

    def get_parameter_details_by_advanced_filter(self, applicable_rat, related_function, related_parameter="", timeout=60):
        """
        Keyword for getting parameter details by advanced filter at Parameter Editor view
        :param applicable_rat: str, applicable rat to filter
        :param related_function: str, related function to filter
        :param related_parameter: str, optional, related parameter to filter
        :param timeout: int, timeout
        :return: dict of str
        """
        return self._detail_panel.get_parameter_details_by_advanced_filter(applicable_rat, related_function,
                                                                          related_parameter, timeout)

    def get_object_name_list(self, object_name, bts_configuration='Current', timeout=60):
        """
        Keyword for getting specific name list at Parameter Editor view

        :param object_name: param object_name: name to locate target object, cannot be none
        :type object_name: str
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :type bts_configuration: str
        :param timeout: timeout
        :type timeout: int
        :return: the name list of specific name
        :rtype: list
        """
        return self._view_panel.get_object_name_list(object_name, bts_configuration, timeout)

    def get_dist_name_list_by_object_name(self, object_name, bts_configuration='Current', timeout=60):
        """
        Keyword for getting specific name list at Parameter Editor view

        :param object_name: param object_name: name to locate target object, cannot be none
        :type object_name: str
        :param bts_configuration: optional, "Current" or "Planned" bts configuration can be used
        :type bts_configuration: str
        :param timeout: timeout
        :type timeout: int
        :return: the name list of specific name
        :rtype: list
        """
        return self._view_panel.get_dist_name_list_by_object_name(object_name, bts_configuration, timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class ParameterEditorPageNavigationPanel(NavigationPanel):

    def __init__(self, driver, screenshot_dir):
        super(ParameterEditorPageNavigationPanel, self).__init__(driver)
        common_action = ConfigurationCommonAction(driver, screenshot_dir=screenshot_dir)
        self.common_actions = {
            'add_object': common_action.add_object,
            'add_new_object': common_action.add_new_object,
            'copy_existing_object': common_action.copy_existing_object,
            'remove_object': common_action.remove_object,
            'undo_object_changes': common_action.undo_object_changes
        }
        self.__dict__.update(self.common_actions)


