    _OBJECT_NAME_MAP_XPATH = '//div[@role="complementary"]//div[@class="p-element ot-text-ellipsis"]'

    _SEARCH_ALL_INPUT_XPATH = '//div[@class="cem-toolbar"]//input[@placeholder="Search with enter"]'
    _CLEAR_GLOBAL_SEARCH = _SEARCH_ALL_INPUT_XPATH + '/following::button[@aria-label="ot-close-minimize-close"]'

